sys_script_include.script:
var MedicationAvailability = Class.create();
MedicationAvailability.prototype = Object.extendsObject(AbstractAjaxProcessor, {

   checkAvailability: function() {
        var medName = this.getParameter('sysparm_medication_name');
        var gr = new GlideRecord('u_medication');
        gr.addQuery('u_medication_name', medName);
        gr.query();
        if (gr.next()) {
            return 'Exists';   // Medication already present
        }
        return 'Not Exists';   // Medication not found
    },

    type: ' MedicationAvailability'
});
